WITH fixes(slug,pos,why) AS (VALUES ('constitucional-acumulacao-ec138-casos',1,'Correto. A EC 138/2025 alterou o art. 37, XVI, b, da Constituição para permitir acumular um cargo de professor com outro de qualquer natureza, desde que haja compatibilidade de horários. Fonte: https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc138.htm'),('constitucional-acumulacao-ec138-casos',20,'Correto. O art. 1º da EC 138/2025 modificou especificamente a alínea b do art. 37, XVI, da Constituição, substituindo a antiga referência a cargo técnico ou científico por outro de qualquer natureza. Fonte: https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc138.htm'),('contabilidade-depreciacao-amortizacao-exaustao',3,'Errado como regra geral. O CPC 27, itens 60 a 62, determina escolher o método que melhor reflita o padrão de consumo dos benefícios econômicos futuros do ativo; não impõe o método linear simplesmente porque o enunciado omitiu o método. O linear pode ser uma hipótese de exercício quando expressamente adotada. Fonte: https://www.cpc.org.br/Arquivos/Documentos/316_CPC_27_rev%2013.pdf')), rebuilt AS (SELECT sm.id,jsonb_agg(CASE WHEN f.pos IS NOT NULL THEN jsonb_set(jsonb_set(e.value,'{why}',to_jsonb(f.why)),'{a}',to_jsonb(CASE WHEN sm.slug='contabilidade-depreciacao-amortizacao-exaustao' THEN false ELSE (e.value->>'a')::boolean END)) ELSE e.value END ORDER BY e.ordinality) quiz FROM study_materials sm CROSS JOIN LATERAL jsonb_array_elements(sm.quiz) WITH ORDINALITY e(value,ordinality) LEFT JOIN fixes f ON f.slug=sm.slug AND f.pos=e.ordinality WHERE sm.slug IN (SELECT DISTINCT slug FROM fixes) GROUP BY sm.id) UPDATE study_materials sm SET quiz=r.quiz,updated_at=now() FROM rebuilt r WHERE sm.id=r.id;